            elif ss_error <= 1.0:
                score += 20
                penalties += (ss_error - 0.5) * 5
            else:
                penalties += (ss_error - 0.5) * 10

    return score - penalties

def tune_pid():
    config = load_config()

    # Balanced ranges - moderate kp, varying ki and kd
    kp_range = [1.5, 2.0, 2.5]
    ki_range = [0.1, 0.15, 0.2]
    kd_range = [0.1, 0.15, 0.2]

    best_score = float('-inf')
    best_params = None

