    total_combos = len(kp_range) * len(ki_range) * len(kd_range)
    print(f"Testing {total_combos} speed PID combinations")

    tested = 0
    for speed_kp in kp_range:
        for speed_ki in ki_range:
            for speed_kd in kd_range:
                tested += 1
                if tested % 10 == 0:
