                speed_gains = {'kp': speed_kp, 'ki': speed_ki, 'kd': speed_kd}
                dist_gains = {'kp': 2.0, 'ki': 0.1, 'kd': 0.0}

                try:
                    results = run_simulation_with_gains(config, speed_gains, dist_gains)
                    score = evaluate_results(results)

                    if score > best_score:
                        best_score = score
