    print(f"Best score: {best_score:.2f}")
    print(f"Speed PID: kp={best_params['speed_gains']['kp']}, ki={best_params['speed_gains']['ki']}, kd={best_params['speed_gains']['kd']}")

if __name__ == '__main__':
    tune_pid()
